import { useCallback, useState, useEffect } from 'react';

const MRU_KEY = 'te2-mru';
const MRU_MAX = 50;

export interface MruItem {
  path: string;
  title: string;
  timestamp: number;
}

function loadMru(): MruItem[] {
  try {
    const raw = localStorage.getItem(MRU_KEY);
    if (raw) return JSON.parse(raw);
  } catch {
    // ignore
  }
  return [];
}

function saveMru(items: MruItem[]): void {
  try {
    localStorage.setItem(MRU_KEY, JSON.stringify(items));
  } catch {
    // ignore
  }
}

export function addToMru(path: string, title: string): void {
  const items = loadMru();
  const filtered = items.filter((i) => i.path !== path);
  filtered.unshift({ path, title, timestamp: Date.now() });
  if (filtered.length > MRU_MAX) {
    filtered.length = MRU_MAX;
  }
  saveMru(filtered);
}

export function removeFromMru(path: string): void {
  const items = loadMru().filter((i) => i.path !== path);
  saveMru(items);
}

export function getMruItems(): MruItem[] {
  return loadMru();
}

export function useMru() {
  const [items, setItems] = useState<MruItem[]>(loadMru);

  const refresh = useCallback(() => {
    setItems(loadMru());
  }, []);

  const add = useCallback((path: string, title: string) => {
    addToMru(path, title);
    refresh();
  }, [refresh]);

  const remove = useCallback((path: string) => {
    removeFromMru(path);
    refresh();
  }, [refresh]);

  // Refresh on mount (in case another window/instance updated MRU)
  useEffect(() => {
    refresh();
  }, [refresh]);

  return { items, add, remove, refresh };
}

import { EditorState, StateField, RangeSetBuilder, RangeSet } from '@codemirror/state';
import { EditorView, Decoration, ViewPlugin, GutterMarker, gutter } from '@codemirror/view';
import { syntaxTree, matchBrackets } from '@codemirror/language';
import type { SyntaxNode } from '@lezer/common';

class PairMarker extends GutterMarker {
  toDOM() {
    const span = document.createElement('span');
    span.className = 'cm-bracket-marker';
    span.textContent = '◆';
    return span;
  }
}

const pairMarkerInstance = new PairMarker();

const pairMatchMark = Decoration.mark({ class: 'cm-matchingBracket' });

function findTagPair(
  state: EditorState,
  pos: number
): { start: { from: number; to: number }; end: { from: number; to: number } } | null {
  const tree = syntaxTree(state);
  if (!tree) return null;

  let node = tree.resolveInner(pos, 1);

  let tagContainer: SyntaxNode | null = null;
  for (let cur: SyntaxNode | null = node; cur; cur = cur.parent) {
    const name = cur.type.name;
    if (name === 'TagName') {
      tagContainer = cur.parent;
      break;
    }
    if (name === 'OpenTag' || name === 'CloseTag') {
      tagContainer = cur;
      break;
    }
  }

  if (!tagContainer) {
    for (let cur: SyntaxNode | null = node; cur; cur = cur.parent) {
      if (cur.type.name === 'Element') {
        tagContainer = cur;
        break;
      }
    }
  }

  if (!tagContainer) return null;

  const getTagName = (container: SyntaxNode): { from: number; to: number } | null => {
    const child = container.getChild('TagName');
    if (child) return { from: child.from, to: child.to };
    const c = container.cursor();
    if (c.firstChild()) {
      do {
        if (c.type.name === 'TagName') return { from: c.from, to: c.to };
      } while (c.nextSibling());
    }
    return null;
  };

  if (tagContainer.type.name === 'Element') {
    const line = state.doc.lineAt(pos);
    let nearestTag: SyntaxNode | null = null;
    let nearestDist = Infinity;

    const stack: SyntaxNode[] = [tagContainer];
    while (stack.length) {
      const current = stack.pop()!;
      if (nearestDist === 0) break;

      if (current.type.name === 'OpenTag' || current.type.name === 'CloseTag') {
        const tagLine = state.doc.lineAt(current.from);
        if (tagLine.number === line.number) {
          const dist = Math.min(Math.abs(current.from - pos), Math.abs(current.to - pos));
          if (dist < nearestDist && dist <= 200) {
            nearestDist = dist;
            nearestTag = current;
          }
        }
      }

      const c = current.cursor();
      if (c.firstChild()) {
        do {
          stack.push(c.node);
        } while (c.nextSibling());
      }
    }

    if (nearestTag) {
      tagContainer = nearestTag;
    } else {
      return null;
    }
  }

  const currentTagName = getTagName(tagContainer);
  if (!currentTagName) return null;

  const element = tagContainer.parent;
  if (!element || element.type.name !== 'Element') return null;

  const isOpen = tagContainer.type.name === 'OpenTag';
  let matchTagName: { from: number; to: number } | null = null;

  if (isOpen) {
    const c = element.cursor();
    if (c.firstChild()) {
      let foundSelf = false;
      do {
        if (c.from === tagContainer.from && c.to === tagContainer.to) {
          foundSelf = true;
          continue;
        }
        if (foundSelf && c.type.name === 'CloseTag') {
          matchTagName = getTagName(c.node);
          break;
        }
      } while (c.nextSibling());
    }
  } else {
    const c = element.cursor();
    if (c.lastChild()) {
      let foundSelf = false;
      do {
        if (c.from === tagContainer.from && c.to === tagContainer.to) {
          foundSelf = true;
          continue;
        }
        if (foundSelf && c.type.name === 'OpenTag') {
          matchTagName = getTagName(c.node);
          break;
        }
      } while (c.prevSibling());
    }
  }

  if (!matchTagName) return null;
  return { start: currentTagName, end: matchTagName };
}

/** Search near pos (skipping whitespace) for the closest bracket on the same line. */
function findBracketNear(
  state: EditorState,
  pos: number
): { pos: number; dir: -1 | 1 } | null {
  const openBrackets = '([{<';
  const closeBrackets = ')]}>';
  const line = state.doc.lineAt(pos);

  for (let p = pos - 1; p >= line.from; p--) {
    const ch = state.doc.sliceString(p, p + 1);
    if (openBrackets.includes(ch)) return { pos: p, dir: 1 };
    if (closeBrackets.includes(ch)) return { pos: p + 1, dir: -1 };
    if (ch !== ' ' && ch !== '\t') break;
  }

  for (let p = pos; p < line.to && p < state.doc.length; p++) {
    const ch = state.doc.sliceString(p, p + 1);
    if (openBrackets.includes(ch)) return { pos: p, dir: 1 };
    if (closeBrackets.includes(ch)) return { pos: p + 1, dir: -1 };
    if (ch !== ' ' && ch !== '\t') break;
  }

  return null;
}

function computeMarkedLines(state: EditorState, cursorPos: number): readonly number[] {
  const lines = new Set<number>();

  const tagMatch = findTagPair(state, cursorPos);
  if (tagMatch) {
    lines.add(state.doc.lineAt(tagMatch.start.from).number);
    lines.add(state.doc.lineAt(tagMatch.end.from).number);
    return Object.freeze([...lines].sort((a, b) => a - b));
  }

  const config = { brackets: '()[]{}<>' as string };
  let match = null;

  const bracketNear = findBracketNear(state, cursorPos);
  if (bracketNear) {
    match = matchBrackets(state, bracketNear.pos, bracketNear.dir, config);
  }

  if (match && match.matched && match.end) {
    lines.add(state.doc.lineAt(match.start.from).number);
    lines.add(state.doc.lineAt(match.end.from).number);
  }

  return Object.freeze([...lines].sort((a, b) => a - b));
}

/** StateField that stores a RangeSet of gutter markers for bracket/tag pair matches. */
const markedLinesField = StateField.define<RangeSet<any>>({
  create(state) {
    const cursorPos = state.selection.main.head;
    const lines = computeMarkedLines(state, cursorPos);
    const builder = new RangeSetBuilder<any>();
    for (const lineNo of lines) {
      const line = state.doc.line(lineNo);
      builder.add(line.from, line.to, pairMarkerInstance);
    }
    return builder.finish();
  },
  update(value, tr) {
    if (!tr.docChanged && tr.startState.selection.eq(tr.state.selection)) return value;
    const cursorPos = tr.state.selection.main.head;
    const lines = computeMarkedLines(tr.state, cursorPos);
    const builder = new RangeSetBuilder<any>();
    for (const lineNo of lines) {
      const line = tr.state.doc.line(lineNo);
      builder.add(line.from, line.to, pairMarkerInstance);
    }
    return builder.finish();
  },
});

/** Gutter that shows ◆ on lines containing a bracket/tag pair match. */
const pairGutter = gutter({
  class: 'cm-pair-gutter',
  markers(view) {
    return view.state.field(markedLinesField);
  },
  initialSpacer() {
    return pairMarkerInstance;
  },
});

/** ViewPlugin that highlights tag names for HTML/XML, and brackets for plain text. */
const bracketAndTagMatcher = ViewPlugin.fromClass(
  class {
    decorations: any;
    constructor(view: EditorView) {
      this.decorations = this.compute(view);
    }
    update(update: any) {
      if (update.docChanged || update.selectionSet) {
        this.decorations = this.compute(update.view);
      }
    }
    compute(view: EditorView) {
      const decorations: any[] = [];
      for (const range of view.state.selection.ranges) {
        if (!range.empty) continue;

        const tagMatch = findTagPair(view.state, range.head);
        if (tagMatch) {
          decorations.push(pairMatchMark.range(tagMatch.start.from, tagMatch.start.to));
          decorations.push(pairMatchMark.range(tagMatch.end.from, tagMatch.end.to));
          continue;
        }

        const config = { brackets: '()[]{}<>' as string };
        let match = null;

        const bracketNear = findBracketNear(view.state, range.head);
        if (bracketNear) {
          match = matchBrackets(view.state, bracketNear.pos, bracketNear.dir, config);
        }

        if (match && match.end) {
          decorations.push(pairMatchMark.range(match.start.from, match.start.to));
          decorations.push(pairMatchMark.range(match.end.from, match.end.to));
        }
      }
      return Decoration.set(decorations, true);
    }
  },
  { decorations: (v: any) => v.decorations }
);

export { markedLinesField, pairGutter, bracketAndTagMatcher };

export function debounce<T extends (...args: any[]) => void>(fn: T, delayMs: number): T {
  let timer: ReturnType<typeof setTimeout> | null = null;
  return ((...args: any[]) => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delayMs);
  }) as T;
}

import { EditorView } from '@codemirror/view';
import { EditorState, EditorSelection } from '@codemirror/state';

export type MarkdownAction =
  | 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'
  | 'bold' | 'italic' | 'strikethrough'
  | 'quote' | 'inlineCode' | 'codeBlock'
  | 'link' | 'image'
  | 'unorderedList' | 'orderedList' | 'taskList'
  | 'table' | 'horizontalRule';

function setHeadingLevel(state: EditorState, level: number) {
  const pos = state.selection.main.head;
  const line = state.doc.lineAt(pos);
  const text = line.text;
  const leading = text.length - text.trimStart().length;
  const trimmed = text.trimStart();
  const match = trimmed.match(/^(#+) /);
  const prefix = '#'.repeat(level) + ' ';

  if (match) {
    return { from: line.from + leading, to: line.from + leading + match[0].length, insert: prefix };
  }
  return { from: line.from + leading, to: line.from + leading, insert: prefix };
}

function toggleLinePrefix(state: EditorState, prefix: string) {
  const { from, to } = state.selection.main;
  const startLine = state.doc.lineAt(from);
  const endLine = state.doc.lineAt(to);
  const changes: { from: number; to: number; insert: string }[] = [];

  for (let i = startLine.number; i <= endLine.number; i++) {
    const line = state.doc.line(i);
    const text = line.text;
    const leading = text.length - text.trimStart().length;
    const trimmed = text.trimStart();

    if (trimmed.startsWith(prefix)) {
      changes.push({ from: line.from + leading, to: line.from + leading + prefix.length, insert: '' });
    } else {
      changes.push({ from: line.from + leading, to: line.from + leading, insert: prefix });
    }
  }

  return changes;
}

export function executeMarkdownAction(view: EditorView, action: MarkdownAction) {
  const state = view.state;
  const { from, to } = state.selection.main;
  const hasSelection = from !== to;

  const changes: { from: number; to: number; insert: string }[] = [];
  let selection = state.selection.main;

  switch (action) {
    case 'h1':
    case 'h2':
    case 'h3':
    case 'h4':
    case 'h5':
    case 'h6': {
      const level = parseInt(action[1]);
      changes.push(setHeadingLevel(state, level));
      break;
    }

    case 'bold': {
      if (hasSelection) {
        const text = state.doc.sliceString(from, to);
        changes.push({ from, to, insert: `**${text}**` });
        selection = EditorSelection.cursor(to);
      } else {
        changes.push({ from, to, insert: '**粗体文本**' });
      }
      break;
    }

    case 'italic': {
      if (hasSelection) {
        const text = state.doc.sliceString(from, to);
        changes.push({ from, to, insert: `*${text}*` });
        selection = EditorSelection.cursor(to);
      } else {
        changes.push({ from, to, insert: '*斜体文本*' });
      }
      break;
    }

    case 'strikethrough': {
      if (hasSelection) {
        const text = state.doc.sliceString(from, to);
        changes.push({ from, to, insert: `~~${text}~~` });
        selection = EditorSelection.cursor(to);
      } else {
        changes.push({ from, to, insert: '~~删除线文本~~' });
      }
      break;
    }

    case 'quote': {
      changes.push(...toggleLinePrefix(state, '> '));
      break;
    }

    case 'inlineCode': {
      if (hasSelection) {
        const text = state.doc.sliceString(from, to);
        changes.push({ from, to, insert: `\`${text}\`` });
        selection = EditorSelection.cursor(to);
      } else {
        changes.push({ from, to, insert: '`行内代码`' });
      }
      break;
    }

    case 'codeBlock': {
      if (hasSelection) {
        const text = state.doc.sliceString(from, to);
        changes.push({ from, to, insert: `\`\`\`\n${text}\n\`\`\`` });
        selection = EditorSelection.cursor(to);
      } else {
        changes.push({ from, to, insert: '\`\`\`\n\n\`\`\`' });
      }
      break;
    }

    case 'link': {
      if (hasSelection) {
        const text = state.doc.sliceString(from, to);
        changes.push({ from, to, insert: `[${text}](url)` });
        selection = EditorSelection.cursor(to);
      } else {
        changes.push({ from, to, insert: '[链接文本](url)' });
      }
      break;
    }

    case 'image': {
      if (hasSelection) {
        const text = state.doc.sliceString(from, to);
        changes.push({ from, to, insert: `![${text}](url)` });
        selection = EditorSelection.cursor(to);
      } else {
        changes.push({ from, to, insert: '![图片描述](url)' });
      }
      break;
    }

    case 'unorderedList': {
      changes.push(...toggleLinePrefix(state, '- '));
      break;
    }

    case 'orderedList': {
      changes.push(...toggleLinePrefix(state, '1. '));
      break;
    }

    case 'taskList': {
      changes.push(...toggleLinePrefix(state, '- [ ] '));
      break;
    }

    case 'table': {
      const table = '| 列1 | 列2 | 列3 |\n| --- | --- | --- |\n| 内容 | 内容 | 内容 |';
      changes.push({ from, to, insert: table });
      break;
    }

    case 'horizontalRule': {
      changes.push({ from, to, insert: '\n---\n' });
      break;
    }
  }

  if (changes.length > 0) {
    view.dispatch({ changes, selection });
    view.focus();
  }
}

import { describe, it, expect, vi } from 'vitest';
import { EditorState } from '@codemirror/state';
import { EditorView } from '@codemirror/view';
import { searchHighlight, setSearchQuery } from './searchHighlight';
import { buildDynamicTheme } from './themes';
import { defaultDarkColors } from './themeDefaults';

describe('searchHighlight', () => {
  it('should create decorations for all matches after setSearchQuery', () => {
    const doc = '{"event_name":"MASTEREQUIP"}\n{"event_name":"MASTEREQUIP"}\n{"event_name":"MASTEREQUIP"}';
    const state = EditorState.create({
      doc,
      extensions: [
        searchHighlight,
        buildDynamicTheme(defaultDarkColors, true),
      ],
    });

    const view = new EditorView({ state });

    // Initial state: no query → no decorations
    const plugin = view.plugin(searchHighlight[1] as any);
    expect(plugin).toBeDefined();
    expect((plugin as any).decorations.size).toBe(0);

    // Dispatch search query
    view.dispatch({
      effects: setSearchQuery.of({ query: 'MASTEREQUIP', caseSensitive: false, regexMode: false }),
    });

    // After dispatch: should have 3 decorations
    const updatedPlugin = view.plugin(searchHighlight[1] as any);
    expect(updatedPlugin).toBeDefined();
    expect((updatedPlugin as any).cachedMatches.length).toBe(3);
    expect((updatedPlugin as any).decorations.size).toBe(3);

    view.destroy();
  });

  it('should mark the active match with cm-searchMatch-selected', () => {
    const doc = '{"event_name":"MASTEREQUIP"}\n{"event_name":"MASTEREQUIP"}';
    const state = EditorState.create({
      doc,
      extensions: [
        searchHighlight,
        buildDynamicTheme(defaultDarkColors, true),
      ],
    });

    const view = new EditorView({ state });

    view.dispatch({
      effects: setSearchQuery.of({ query: 'MASTEREQUIP', caseSensitive: false, regexMode: false }),
    });

    // Move cursor into the first match
    view.dispatch({ selection: { anchor: 15, head: 26 } });

    const plugin = view.plugin(searchHighlight[1] as any);
    const decos = (plugin as any).decorations;

    // Check that at least one decoration has the selected class
    let hasSelected = false;
    decos.between(0, doc.length, (_from: number, _to: number, value: any) => {
      if (value.spec?.class?.includes('cm-searchMatch-selected')) {
        hasSelected = true;
      }
    });
    expect(hasSelected).toBe(true);

    view.destroy();
  });

  it('should only scan viewport area for large files (>200k chars)', () => {
    const prefix = 'MASTEREQUIP';
    const middle = 'x'.repeat(200_000);
    const suffix = 'MASTEREQUIP';
    const doc = prefix + middle + suffix;

    const state = EditorState.create({
      doc,
      extensions: [searchHighlight],
    });
    const view = new EditorView({ state });

    // Mock viewport to only cover the prefix area
    Object.defineProperty(view, 'viewport', {
      value: { from: 0, to: prefix.length },
      configurable: true,
    });

    view.dispatch({
      effects: setSearchQuery.of({ query: 'MASTEREQUIP', caseSensitive: false, regexMode: false }),
    });

    const plugin = view.plugin(searchHighlight[1] as any);
    expect((plugin as any).cachedMatches.length).toBe(1);
    expect((plugin as any).cachedMatches[0].from).toBe(0);

    view.destroy();
  });

  it('should rescan viewport when it moves in large files', () => {
    const prefix = 'MASTEREQUIP';
    const middle = 'x'.repeat(200_000);
    const suffix = 'MASTEREQUIP';
    const doc = prefix + middle + suffix;

    const state = EditorState.create({
      doc,
      extensions: [searchHighlight],
    });
    const view = new EditorView({ state });

    // Start with viewport at prefix
    Object.defineProperty(view, 'viewport', {
      value: { from: 0, to: prefix.length },
      configurable: true,
    });

    view.dispatch({
      effects: setSearchQuery.of({ query: 'MASTEREQUIP', caseSensitive: false, regexMode: false }),
    });

    const plugin = view.plugin(searchHighlight[1] as any);
    expect((plugin as any).cachedMatches.length).toBe(1);
    expect((plugin as any).cachedMatches[0].from).toBe(0);

    // Move viewport to suffix area and manually trigger rescan
    Object.defineProperty(view, 'viewport', {
      value: { from: prefix.length + middle.length, to: doc.length },
      configurable: true,
    });

    (plugin as any).rescanViewport(view);

    expect((plugin as any).cachedMatches.length).toBe(1);
    expect((plugin as any).cachedMatches[0].from).toBe(prefix.length + middle.length);

    view.destroy();
  });
});

import { EditorView, Decoration, ViewPlugin, ViewUpdate, type DecorationSet } from '@codemirror/view';
import { StateField, StateEffect, RangeSetBuilder } from '@codemirror/state';
import { SearchCursor, RegExpCursor } from '@codemirror/search';

export interface SearchQuery {
  query: string;
  caseSensitive: boolean;
  regexMode: boolean;
}

export const setSearchQuery = StateEffect.define<SearchQuery | null>();

const searchHighlightField = StateField.define<SearchQuery | null>({
  create() {
    return null;
  },
  update(value, tr) {
    for (const effect of tr.effects) {
      if (effect.is(setSearchQuery)) {
        return effect.value;
      }
    }
    return value;
  },
});

const MAX_HIGHLIGHT_CHARS = 200_000;
const VIEWPORT_BUFFER = 5000;

function getMatches(
  doc: any,
  query: SearchQuery,
  from: number,
  to: number
): { from: number; to: number }[] {
  if (!query.query) return [];
  const matches: { from: number; to: number }[] = [];
  try {
    if (query.regexMode) {
      const cursor = new RegExpCursor(doc, query.query, { ignoreCase: !query.caseSensitive }, from, to);
      if (!cursor) return matches;
      let result;
      while (!(result = cursor.next()).done) {
        matches.push({ from: result.value.from, to: result.value.to });
      }
    } else {
      const normalize = query.caseSensitive ? undefined : (s: string) => s.toLowerCase();
      const cursor = new SearchCursor(doc, query.query, from, to, normalize);
      let result;
      while (!(result = cursor.next()).done) {
        matches.push({ from: result.value.from, to: result.value.to });
      }
    }
  } catch {
    // Invalid regex or other error
  }
  return matches;
}

const searchHighlightPlugin = ViewPlugin.fromClass(
  class {
    decorations: DecorationSet = Decoration.none;
    cachedMatches: { from: number; to: number }[] = [];
    cachedQuery: SearchQuery | null = null;

    constructor(view: EditorView) {
      this.rebuild(view);
    }

    update(update: ViewUpdate) {
      const query = update.state.field(searchHighlightField);
      const prevQuery = update.startState.field(searchHighlightField);

      const queryChanged =
        query?.query !== prevQuery?.query ||
        query?.caseSensitive !== prevQuery?.caseSensitive ||
        query?.regexMode !== prevQuery?.regexMode;

      if (queryChanged || update.docChanged) {
        this.rebuild(update.view);
      } else if (update.viewportChanged && update.view.state.doc.length > MAX_HIGHLIGHT_CHARS) {
        this.rescanViewport(update.view);
      } else if (update.selectionSet) {
        this.updateSelection(update.view);
      }
    }

    /** Re-scan matches when query or document changes. */
    rebuild(view: EditorView) {
      const query = view.state.field(searchHighlightField);
      this.cachedQuery = query;

      if (!query || !query.query) {
        this.cachedMatches = [];
        this.decorations = Decoration.none;
        return;
      }

      this.rescanViewport(view);
    }

    /** Scan visible viewport (with buffer) for large files, or full doc for small files. */
    rescanViewport(view: EditorView) {
      const query = this.cachedQuery;
      if (!query) return;

      const docLen = view.state.doc.length;
      let from: number;
      let to: number;

      if (docLen <= MAX_HIGHLIGHT_CHARS) {
        from = 0;
        to = docLen;
      } else {
        const viewport = view.viewport;
        from = Math.max(0, viewport.from - VIEWPORT_BUFFER);
        to = Math.min(docLen, viewport.to + VIEWPORT_BUFFER);
        if (to - from > MAX_HIGHLIGHT_CHARS) {
          to = from + MAX_HIGHLIGHT_CHARS;
        }
      }

      this.cachedMatches = getMatches(view.state.doc, query, from, to);
      this.updateSelection(view);
    }

    /** Re-build decorations from cached matches when only selection changes. */
    updateSelection(view: EditorView) {
      if (!this.cachedMatches.length) {
        this.decorations = Decoration.none;
        return;
      }

      const selection = view.state.selection.main;
      const builder = new RangeSetBuilder<Decoration>();

      for (const match of this.cachedMatches) {
        const isActive = match.from <= selection.head && match.to >= selection.head;
        const deco = Decoration.mark({
          class: isActive
            ? 'cm-searchMatch cm-searchMatch-selected'
            : 'cm-searchMatch',
        });
        builder.add(match.from, match.to, deco);
      }

      this.decorations = builder.finish();
    }
  },
  { decorations: (v) => v.decorations }
);

export const searchHighlight = [searchHighlightField, searchHighlightPlugin];
